package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {









    @Test
    public void testCreateNumber_IntegerTypes() {
        // Test Integer path
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));

        // Test Long path
        assertEquals(Long.valueOf(123456789L), NumberUtils.createNumber("123456789"));

        // Test BigInteger path (exceeding Long)
        String bigIntStr = "123456789012345678901234567890";
        Number bigInt = NumberUtils.createNumber(bigIntStr);
        assertTrue(bigInt instanceof BigInteger);
        assertEquals(new BigInteger(bigIntStr), bigInt);
    }














}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {











    @Test
    public void testCreateNumber_FloatingPointTypes() {
        // Test Float
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23f"));
        assertEquals(Float.valueOf(1.23F), NumberUtils.createNumber("1.23F"));

        // Test Double
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23d"));
        assertEquals(Double.valueOf(1.23D), NumberUtils.createNumber("1.23D"));

        // Test BigDecimal (via fallback or explicit)
        assertEquals(new BigDecimal("1.23"), NumberUtils.createNumber("1.23"));
    }












}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {













    @Test
    public void testCreateNumber_ScientificNotation() {
        // Integer-like scientific
        assertEquals(Long.valueOf(100L), NumberUtils.createNumber("1e2"));

        // Float scientific
        assertEquals(Float.valueOf(1.2e2f), NumberUtils.createNumber("1.2e2f"));

        // Double scientific
        assertEquals(Double.valueOf(1.2e2d), NumberUtils.createNumber("1.2e2d"));

        // BigDecimal scientific
        assertEquals(new BigDecimal("1.2e2"), NumberUtils.createNumber("1.2e2"));
    }










}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {















    @Test
    public void testCreateNumber_Suffixes() {
        // Long suffix L
        assertEquals(Long.valueOf(100L), NumberUtils.createNumber("100L"));
        assertEquals(Long.valueOf(-100L), NumberUtils.createNumber("-100L"));

        // BigInteger via Long suffix (too large)
        String hugeLong = "9223372036854775808"; // Long.MAX_VALUE + 1
        Number hugeNum = NumberUtils.createNumber(hugeLong + "L");
        assertTrue(hugeNum instanceof BigInteger);
    }








}

