package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {



















    @Test
    public void testCreateNumber_EdgeCasePrecision() {
        // Test the "allZeros" logic for precision protection
        // If input is "0.000...0" but not actually zero, it should fallback to BigDecimal
        // to avoid float precision loss.
        String tiny = "0.0000000000000000000000000000000001";
        Number n = NumberUtils.createNumber(tiny);
        assertTrue(n instanceof BigDecimal);
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
