import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {





















    @Test
    public void testCreateNumber_InvalidFormats() {
        // expPos logic: expPos < decPos
        try {
            NumberUtils.createNumber("1e.2");
            fail();
        } catch (NumberFormatException e) {}

        // expPos > length
        try {
            NumberUtils.createNumber("1e");
            fail();
        } catch (NumberFormatException e) {}

        // Invalid last char for non-suffix
        try {
            NumberUtils.createNumber("123x");
            fail();
        } catch (NumberFormatException e) {}
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen5Test {























    @Test
    public void testCreateNumber_ComplexScientific() {
        // Testing the logic: if (!Character.isDigit(lastChar) && lastChar != '.')
        // with an exponent at the end
        // "1.2e2f" -> numeric="1.2e2", lastChar='f', exp="2"
        assertEquals(Float.valueOf(120.0f), NumberUtils.createNumber("1.2e2f"));

        // "1.2e2d"
        assertEquals(Double.valueOf(120.0d), NumberUtils.createNumber("1.2e2d"));
    }
}
